import { useEffect, useRef } from "react";
import { placeSidePanels, pluginHost, useContributions } from "../plugins/host";
import { Rail } from "../plugins/Rail";
import { SettingsScreen } from "../settings/SettingsScreen";
import { HomeScreen } from "./HomeScreen";
import { useShellStore } from "./store";
import { TopBar } from "./TopBar";

export function App() {
  const theme = useShellStore((s) => s.theme);
  const view = useShellStore((s) => s.view);
  const setTheme = useShellStore((s) => s.setTheme);
  const setView = useShellStore((s) => s.setView);
  const init = useShellStore((s) => s.init);
  const backButtonRef = useRef<HTMLButtonElement>(null);
  const rails = placeSidePanels(useContributions(pluginHost.sidePanels));

  useEffect(() => {
    init();
  }, [init]);

  useEffect(() => {
    document.body.dataset.theme = theme;
  }, [theme]);

  // Hold-to-talk is focused-window only (decision D-10): plain renderer
  // keydown/keyup on right Alt while the app is focused - no global hooks,
  // no Input Monitoring permission, ever. Esc abandons.
  useEffect(() => {
    const down = (event: KeyboardEvent) => {
      const store = useShellStore.getState();
      if (event.key === "Escape") {
        if (store.phase === "recording") {
          store.abandonRecording();
        } else if (store.view === "settings") {
          store.setView("home");
        }
        return;
      }
      if (event.key === "Alt" && event.location === 2 && !event.repeat) {
        event.preventDefault();
        store.startRecording();
      }
    };
    const up = (event: KeyboardEvent) => {
      const store = useShellStore.getState();
      if (event.key === "Alt" && event.location === 2 && store.phase === "recording") {
        event.preventDefault();
        store.acceptRecording();
      }
    };
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
    };
  }, []);

  // Landing in settings moves focus to the back control so keyboard users
  // are not stranded in the previous screen's tree.
  useEffect(() => {
    if (view === "settings") {
      backButtonRef.current?.focus();
    }
  }, [view]);

  const home = view === "home";

  // The home shell (D5): two dock rails frame a STAGE that holds the fixed
  // geometry. An empty rail is zero-width (design/styles.css), so with both
  // empty the stage is the whole window and nothing below moves. The rails
  // are home-only in v1; Settings keeps its own centred composition. The
  // activity feed and the crew strip are panels on the left rail (phase 2,
  // the built-in plugin) - FYI lives in the feed (captain refinement 4a),
  // and the feed shows whenever it has lines, so an answered turn with zero
  // cards still leaves its trace there.
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: "var(--bg-0)",
        overflow: "hidden",
        fontFamily: "var(--font-ui)",
      }}
    >
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "stretch" }}>
        {home && <Rail side="left" panels={rails.left} theme={theme} />}
        <div
          data-stage=""
          style={{
            position: "relative",
            flex: 1,
            minWidth: 0,
            // Stage-relative sizes (cqw) for anything that must not assume
            // the stage is the window.
            containerType: "inline-size",
          }}
        >
          {home && <HomeScreen />}
          {view === "settings" && <SettingsScreen />}
        </div>
        {home && <Rail side="right" panels={rails.right} theme={theme} />}
      </div>
      <TopBar
        view={view}
        theme={theme}
        onTheme={() => setTheme(theme === "dark" ? "light" : "dark")}
        onSettings={() => setView("settings")}
        onBack={() => setView("home")}
        backButtonRef={backButtonRef}
      />
    </div>
  );
}

