import type { FrameTheme } from "@shared/plugins/frameDocument";
import type { RailSide } from "@shared/plugins/manifest";
import { useMemo, useSyncExternalStore } from "react";
import type { SidePanelContribution } from "./contributions";
import { FrameMount } from "./frames/FrameMount";
import { pluginHost } from "./host";
import { railStore, usePanelCollapsed } from "./railStore";
import { SidePanelChrome } from "./SidePanelChrome";

/**
 * One of the two dock rails (D5). The rail renders only its mounted
 * panels, and a panel whose source says `null` renders nothing at all - so
 * an empty rail is an empty element, and the stylesheet's `:empty` rule
 * gives it zero width, no padding, and no paint (design/styles.css). That
 * is the whole of "empty means invisible": no measurement, no flag, no
 * frame of chrome before the first data arrives.
 */
export function Rail({
  side,
  panels,
  theme,
}: {
  side: RailSide;
  panels: readonly SidePanelContribution[];
  /** The shell's theme, pushed into every frame the rail mounts. */
  theme: FrameTheme;
}) {
  return (
    <div data-rail={side}>
      {panels.map((panel) => (
        <PanelMount key={panel.id} panel={panel} theme={theme} />
      ))}
    </div>
  );
}

function PanelMount({ panel, theme }: { panel: SidePanelContribution; theme: FrameTheme }) {
  const content = useSyncExternalStore(panel.source.subscribe, panel.source.get, panel.source.get);
  const collapsed = usePanelCollapsed(panel.id);
  if (content === null) return null;
  return (
    <SidePanelChrome
      id={panel.id}
      title={panel.title}
      attribution={panel.attribution}
      size={panel.size}
      collapsed={collapsed}
      onToggleCollapsed={() => railStore.toggleCollapsed(panel.id)}
    >
      {panel.frame ? (
        <FramePanelBody panel={panel} theme={theme} />
      ) : (
        panel.Body && <panel.Body content={content} />
      )}
    </SidePanelChrome>
  );
}

/**
 * A Tier-2 panel: its template in the frame vehicle, inside the host's
 * chrome (docs/ui-plugins.md, phase 2). The mount lives as long as the
 * panel has something to show; its data is pushed over the bridge from the
 * reads the plugin declared. A panel is display: the only actions its
 * frame may raise are the pointing gestures the binding declared (the now
 * panel's "open this row"), and the controller refuses every other id.
 * A `fill` panel's frame takes the body's height; a `content` panel's
 * follows the document's own height as the bridge reports it, from zero,
 * so a strip is exactly as tall as it draws.
 */
function FramePanelBody({ panel, theme }: { panel: SidePanelContribution; theme: FrameTheme }) {
  const actions = useMemo(() => Object.keys(panel.actions ?? {}), [panel.actions]);
  if (!panel.frame) return null;
  return (
    <FrameMount
      title={panel.title}
      template={panel.frame}
      spec={{
        pluginId: panel.pluginId,
        reads: pluginHost.declaredReads(panel.pluginId),
        actions,
        onAction: (id, value) => panel.actions?.[id]?.(value),
      }}
      theme={theme}
      layout={panel.size === "fill" ? "fill" : "auto"}
      minAutoHeight={0}
      maxAutoHeight={FRAME_PANEL_MAX_AUTO_HEIGHT}
    />
  );
}

/** The most rail height a `content` panel's frame may grow to on its own. */
export const FRAME_PANEL_MAX_AUTO_HEIGHT = 320;

import { nowPanelHasRows } from "@shared/nowPanel";
import type { FrameTemplate } from "@shared/plugins/frameDocument";
import { useShellStore } from "../../app/store";
import { GeneralTab } from "../../settings/GeneralTab";
import { SubscriptionsTab } from "../../settings/SubscriptionsTab";
import { type PluginBindings, sidePanelBinding } from "../contributions";
import type { PluginHost } from "../host";
import { appReadExecutor } from "../reads/appExecutor";
import { createReadPanelSource } from "../reads/readPanelSource";
import activityScript from "./activity/activity.frame.js?raw";
import activityHtml from "./activity/activity.html?raw";
import crewScript from "./crew/crew.frame.js?raw";
import crewHtml from "./crew/crew.html?raw";
import { builtinManifest } from "./manifest";
import nowScript from "./now/now.frame.js?raw";
import nowHtml from "./now/now.html?raw";
import { openFromNow } from "./now/nowActions";
import observeScript from "./observe/observe.frame.js?raw";
import observeHtml from "./observe/observe.html?raw";
import recordScript from "./record/record.frame.js?raw";
import recordHtml from "./record/record.html?raw";

/**
 * Binds the built-in manifest to the code that serves it. Called once from
 * the renderer entry against the app's host; tests call it against their
 * own `new PluginHost()`.
 *
 * Observe is the first Tier-2 contribution (docs/ui-plugins.md, phase 1):
 * a template in the frame vehicle, fed by the reads the manifest declares,
 * with no React of its own. The other two tabs stay Tier 1.
 *
 * The activity feed and the crew strip are the phase-2 contributions: two
 * Tier-2 side panels on the left rail. Each panel's frame paints the data
 * it subscribes to over the bridge; each panel's SOURCE - whether there is
 * anything to show at all - is the same read projected to a yes or a null,
 * so a feed with no lines and a crew of nobody leave the rail empty, and
 * a fresh window is pixel-identical to one without rails (D5 rule 1).
 *
 * The now panel (task-system P4) is the right rail's one panel, on the same
 * vehicle: `tasks.board` projected to "any row the panel lists?" for its
 * visibility, and one declared action, `open`, which is a pointing gesture
 * the host answers by bringing a decision card forward or opening the
 * task-record card (./now/nowActions.ts). The record card's body is the
 * fourth template here, instantiated per opened task (`recordTemplate`).
 */
export const observeTemplate: FrameTemplate = { html: observeHtml, script: observeScript };
export const activityTemplate: FrameTemplate = { html: activityHtml, script: activityScript };
export const crewTemplate: FrameTemplate = { html: crewHtml, script: crewScript };
export const nowTemplate: FrameTemplate = { html: nowHtml, script: nowScript };

/** The record template's root carries the task it shows; the script reads it back. */
const RECORD_TASK_ID_SLOT = "__TASK_ID__";

/**
 * The task-record card's body for one task: the record template with the
 * task id stamped on its root, so the frame can subscribe to `tasks.detail`
 * for exactly that task. The id is attribute-escaped although the record's
 * ids are plain hex - the frame boundary is not the place to assume that.
 */
export function recordTemplate(taskId: string): FrameTemplate {
  const escaped = taskId.replace(
    /[&<>"']/g,
    (char) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char] ?? char,
  );
  return { html: recordHtml.replace(RECORD_TASK_ID_SLOT, escaped), script: recordScript };
}

export const builtinBindings: PluginBindings = {
  settingsSections: {
    general: { Component: GeneralTab },
    subscriptions: { Component: SubscriptionsTab },
    observe: {
      frame: observeTemplate,
      // Main already gates the IPC; a failure to ask reads as "off".
      enabled: () =>
        window.firstmate.observe
          .enabled()
          .then((result) => result.enabled)
          .catch(() => false),
    },
  },
  sidePanels: {
    activity: sidePanelBinding({
      frame: activityTemplate,
      source: createReadPanelSource(appReadExecutor, "feed.recent", {}, (lines) =>
        lines.length > 0 ? true : null,
      ),
    }),
    crew: sidePanelBinding({
      frame: crewTemplate,
      source: createReadPanelSource(appReadExecutor, "crew.counts", {}, (counts) =>
        counts.working + counts.idle + counts.queued + counts.waiting > 0 ? true : null,
      ),
    }),
    now: sidePanelBinding({
      frame: nowTemplate,
      source: createReadPanelSource(appReadExecutor, "tasks.board", {}, (board) =>
