      ),
      actions: {
        open: (value) => {
          openFromNow(value, useShellStore.getState());
        },
      },
    }),
  },
};

export function registerBuiltinPlugin(host: PluginHost): () => void {
  return host.registerPlugin(builtinManifest, builtinBindings, { firstParty: true });
