import type { FrameLocator, Locator, Page } from "@playwright/test";

/**
 * The rails' built-in panels (docs/ui-plugins.md, phase 2; task-system P4).
 * The activity feed, the crew strip, and the now panel are Tier-2 frames,
 * so a feed line, the strip, or a task row lives inside
 * `iframe[title="Activity"]` / `iframe[title="Crew"]` / `iframe[title="Now"]`
 * and page-level locators do not see it; the task-record card's body is a
 * frame too. Every spec that reads one goes through here, so the vehicle
 * is named in one place.
 */

export function activityFrame(page: Page): FrameLocator {
  return page.frameLocator('iframe[title="Activity"]');
}

export function crewFrame(page: Page): FrameLocator {
  return page.frameLocator('iframe[title="Crew"]');
}

export function nowFrame(page: Page): FrameLocator {
  return page.frameLocator('iframe[title="Now"]');
}

/** One now-panel row by its task key, as the frame paints it. */
export function nowRow(page: Page, key: string): Locator {
  return nowFrame(page).locator(`[data-now-row][data-now-key="${key}"]`);
}

/** The open task-record card's body frame. */
export function recordFrame(page: Page): FrameLocator {
  return page.frameLocator('iframe[title="Task record body"]');
}

/** One feed row by its text, as the frame paints it. */
export function feedLine(page: Page, text: string | RegExp): Locator {
  return activityFrame(page).locator("[data-feed-row]").getByText(text);
}

/** The crew strip: one button whose name carries every count. */
export function crewStrip(page: Page, name: RegExp = /Crew overview:/): Locator {
  return crewFrame(page).getByRole("button", { name });
}

