test("landing a task closes its record as done and keeps the row and session (D2)", async () => {
  const { page, userDataDir } = launched;
  const [survivor] = readdirSync(join(userDataDir, "worktrees")) as [string];
  const repoName = registeredRepo.split("/").at(-1) as string;
  await expect(page.getByRole("img", { name: "Firstmate - idle" })).toBeVisible({
    timeout: 20_000,
  });
  const input = page.getByPlaceholder("type, or press/hold right ⌥ to talk");
  await input.click();
  await input.fill(`${LAND_PROMPT_MARKER}second parallel task in ${repoName}`);
  await input.press("Enter");

  await expect(feedLine(page, /work landed \(fast-forward\)/)).toBeVisible({ timeout: 30_000 });
  await expect
    .poll(() => execFileSync("git", ["-C", registeredRepo, "branch", "--list"]).toString(), {
      timeout: 15_000,
    })
    .not.toContain(`fm/task-${survivor}`);
  expect(existsSync(join(userDataDir, "worktrees", survivor))).toBe(false);
  // The row survives landing: done/landed, keyed under the repo's project,
  // with its session JSONL still on disk for Observe and the corpus export.
  const row = taskRow(userDataDir, survivor);
  expect(row).toMatchObject({
    status: "done",
    closed_reason: "landed",
    workspace_state: "removed",
  });
  expect(row?.key).toMatch(/^[A-Z0-9]{2,4}-\d+$/);
  expect(row?.project_id).not.toBe("scratch");
  expect(existsSync(join(userDataDir, "crewmates", survivor, "sessions"))).toBe(true);
  // Nothing is crew any more; the strip leaves the rail.
  await expect(page.locator('iframe[title="Crew"]')).toHaveCount(0, { timeout: 10_000 });
});

import { existsSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "@playwright/test";
import Database from "better-sqlite3";
import { type LaunchedApp, launchApp } from "./launch";
import { FINISH_PROMPT_MARKER, MOCK_COMPLETION_TEXT, SPAWN_PROMPT_MARKER } from "./mockProvider";
import { crewStrip, feedLine } from "./rails";

/**
 * The task record (task-system P0): a task is a record, not a runtime
 * handle. A crewmate's report lands on its row, so after a quit and relaunch
 * the crew is still listed - idle, steerable by resume - with the same
 * report (crew_status reads the record), the Firstmate's context block names
 * it, and settling it works on the durable row.
 */

let launched: LaunchedApp;

type TaskRow = {
  id: string;
  key: string;
  status: string;
  activity: string | null;
  closed_reason: string | null;
  outcome: string | null;
  outcome_summary: string | null;
  assignee: string | null;
};

function readTasks(userDataDir: string): TaskRow[] {
  const db = new Database(join(userDataDir, "firstmate.db"), { readonly: true });
  try {
    return db
      .prepare(
        "SELECT id, key, status, activity, closed_reason, outcome, outcome_summary, assignee FROM tasks ORDER BY created_at",
      )
      .all() as TaskRow[];
  } finally {
    db.close();
  }
}

function timelineKinds(userDataDir: string, taskId: string): string[] {
  const db = new Database(join(userDataDir, "firstmate.db"), { readonly: true });
  try {
    return (
      db.prepare("SELECT kind FROM task_events WHERE task_id = ? ORDER BY at, id").all(taskId) as {
        kind: string;
      }[]
    ).map((row) => row.kind);
  } finally {
    db.close();
  }
}

test.beforeAll(async () => {
  launched = await launchApp({ withMockProvider: true });
});

test.afterAll(async () => {
  await launched.close();
});

test("a crewmate's report lands on its record", async () => {
  const { page, userDataDir } = launched;
  const input = page.getByPlaceholder("type, or press/hold right ⌥ to talk");
  await input.click();
  await input.fill(`${SPAWN_PROMPT_MARKER} write a short status note`);
  await input.press("Enter");
  await expect(feedLine(page, /crewmate \d+ reported - write a short status note/)).toBeVisible({
    timeout: 30_000,
  });
  await expect(page.getByRole("img", { name: "Firstmate - idle" })).toBeVisible({
    timeout: 20_000,
  });

  await expect
    .poll(() => readTasks(userDataDir)[0]?.outcome, { timeout: 10_000 })
    .toBe(MOCK_COMPLETION_TEXT);
  const [row] = readTasks(userDataDir);
  expect(row).toMatchObject({
    key: "SCR-1",
    status: "active",
    activity: "idle",
    assignee: "crewmate 1",
    outcome_summary: "Steady as she goes.",
  });
  // The captain's words that caused the spawn ride the timeline (P1 capture).
  expect(timelineKinds(userDataDir, row?.id as string)).toEqual([
    "created",
    "dispatched",
    "ask",
    "report",
  ]);
});

test("after a restart the crew is still listed with its report, and settling works on the record", async () => {
  const { userDataDir } = launched;
  const [row] = readTasks(userDataDir);
  const taskId = row?.id as string;
  await launched.close();
  launched = await launchApp({ withMockProvider: true, userDataDir });
  const { page, mockProvider } = launched;

  // The record makes the crewmate crew again: one idle on the strip, no
  // runtime behind it, the report intact on the row.
  await expect(crewStrip(page, /1 idle/)).toBeVisible({ timeout: 20_000 });
  expect(readTasks(userDataDir)[0]).toMatchObject({
    id: taskId,
    status: "active",
    activity: "idle",
    outcome: MOCK_COMPLETION_TEXT,
  });

  // Firstmate's context block lists it from crew_status, which is how the
  // mock finds the task id to settle; finishing closes the durable row.
  const input = page.getByPlaceholder("type, or press/hold right ⌥ to talk");
  await input.click();
  await input.fill(`${FINISH_PROMPT_MARKER}write a short status note`);
  await input.press("Enter");
  await expect(
    feedLine(page, "crewmate decommissioned - write a short status note completed"),
  ).toBeVisible({ timeout: 30_000 });
  const body = mockProvider?.requestBodies().at(-1) ?? "";
  expect(body).toContain(`- task ${taskId} idle`);

  expect(readTasks(userDataDir)[0]).toMatchObject({
    id: taskId,
    status: "delivered",
    closed_reason: "finished",
    outcome: MOCK_COMPLETION_TEXT,
  });
  // The finish turn's ask attached to the task it settled (P1 capture).
  expect(timelineKinds(userDataDir, taskId)).toEqual([
    "created",
    "dispatched",
    "ask",
    "report",
    "ask",
    "status",
  ]);
  // Finished keeps the worktree and the session, as before.
  expect(readdirSync(join(userDataDir, "worktrees"))).toHaveLength(1);
  expect(existsSync(join(userDataDir, "crewmates", taskId, "sessions"))).toBe(true);
  await expect(page.locator('iframe[title="Crew"]')).toHaveCount(0, { timeout: 10_000 });
});

